import { Controller, Delete, Get, HttpCode, Post, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const BUSINESS_TYPES = ['고유목적사업', '수익사업', '공통사업'];
const PROJECT_TYPES = ['공통', '직접사업'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
// 가정: 신규 등록 시 사용 여부 초기값은 '사용'
const INITIAL_USE_STATUS = '사용';

type Db = {
  query: (sql: string, params?: Record<string, unknown>) => Promise<any[]>;
  execute: (sql: string, params?: Record<string, unknown>) => Promise<number>;
};

function optText(value: unknown, max: number): string | null {
  if (value === undefined || value === null) {
    return null;
  }
  if (typeof value !== 'string') {
    throw new ApiError(400, 'VALIDATION_FAILED', '글자로 입력해야 하는 값이 형식에 맞지 않습니다.');
  }
  const trimmed = value.trim();
  if (trimmed === '') {
    return null;
  }
  if (trimmed.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', '입력 길이가 허용 범위를 넘었습니다.');
  }
  return trimmed;
}

function requiredText(value: unknown, max: number): string {
  const text = optText(value, max);
  if (text === null) {
    throw new ApiError(422, 'PROJECT_PERIOD_INVALID', '필수 값이 누락되었습니다.');
  }
  return text;
}

function requiredId(value: unknown): number {
  if (value === undefined || value === null || value === '') {
    throw new ApiError(422, 'PROJECT_PERIOD_INVALID', '필수 값이 누락되었습니다.');
  }
  if (typeof value !== 'number' || !Number.isInteger(value) || value <= 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', 'ID는 양의 정수여야 합니다.');
  }
  return value;
}

function requiredDate(value: unknown): string {
  const text = requiredText(value, 10);
  if (!DATE_PATTERN.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '날짜는 YYYY-MM-DD 형식이어야 합니다.');
  }
  return text;
}

function parseProject(data: Record<string, unknown>) {
  const projectCode = requiredText(data['projectCode'], 30);
  const projectName = requiredText(data['projectName'], 200);
  const startDate = requiredDate(data['startDate']);
  const endDate = requiredDate(data['endDate']);
  const businessType = requiredText(data['businessType'], 20);
  const projectType = requiredText(data['projectType'], 20);
  const departmentId = requiredId(data['departmentId']);
  const managerId = requiredId(data['managerId']);
  if (!BUSINESS_TYPES.includes(businessType)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '사업 구분은 고유목적사업, 수익사업, 공통사업 중 하나여야 합니다.');
  }
  if (!PROJECT_TYPES.includes(projectType)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트 유형은 공통, 직접사업 중 하나여야 합니다.');
  }
  let amount: number | null = null;
  const rawAmount = data['amount'];
  if (rawAmount !== undefined && rawAmount !== null && rawAmount !== '') {
    if (typeof rawAmount !== 'number' || !Number.isFinite(rawAmount) || rawAmount < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트 금액은 0 이상의 숫자여야 합니다.');
    }
    amount = rawAmount;
  }
  const rawIds = data['permittedEmployeeIds'];
  let permittedIds: number[] = [];
  if (rawIds !== undefined && rawIds !== null) {
    if (!Array.isArray(rawIds)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '사용 권한 대상은 목록이어야 합니다.');
    }
    for (const id of rawIds) {
      if (typeof id !== 'number' || !Number.isInteger(id) || id <= 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '사용 권한 대상 ID가 올바르지 않습니다.');
      }
    }
    permittedIds = Array.from(new Set(rawIds as number[]));
  }
  return {
    projectCode,
    projectName,
    projectShortName: optText(data['projectShortName'], 100),
    managingAccount: optText(data['managingAccount'], 50),
    startDate,
    endDate,
    businessType,
    projectType,
    departmentId,
    managerId,
    amount,
    purpose: optText(data['purpose'], 100000),
    content: optText(data['content'], 100000),
    permittedIds,
  };
}

async function verifyReferences(db: Db, p: ReturnType<typeof parseProject>): Promise<void> {
  const period = await db.query(
    'SELECT CAST(:endDate AS date) >= CAST(:startDate AS date) AS "ok"',
    { startDate: p.startDate, endDate: p.endDate },
  );
  if (!period[0].ok) {
    throw new ApiError(422, 'PROJECT_PERIOD_INVALID', '종료일은 시작일보다 빠를 수 없습니다.');
  }
  const dept = await db.query('SELECT department_id FROM department WHERE department_id = :id', { id: p.departmentId });
  if (dept.length === 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '주관부서를 찾을 수 없습니다.');
  }
  const manager = await db.query('SELECT employee_id FROM employee WHERE employee_id = :id', { id: p.managerId });
  if (manager.length === 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', '담당자를 찾을 수 없습니다.');
  }
  for (const id of p.permittedIds) {
    const emp = await db.query('SELECT employee_id FROM employee WHERE employee_id = :id', { id });
    if (emp.length === 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '사용 권한 대상 임직원을 찾을 수 없습니다.');
    }
  }
}

async function savePermissions(db: Db, projectId: number, ids: number[]): Promise<void> {
  await db.execute(
    'DELETE FROM project_permission WHERE project_id = :projectId AND sub_project_id IS NULL',
    { projectId },
  );
  for (const employeeId of ids) {
    await db.execute(
      'INSERT INTO project_permission (project_id, sub_project_id, employee_id, created_at, updated_at) VALUES (:projectId, NULL, :employeeId, now(), now())',
      { projectId, employeeId },
    );
  }
}

async function writeHistory(
  db: Db,
  projectId: number,
  changeType: string,
  userId: string,
  before: unknown,
  after: unknown,
): Promise<void> {
  await db.execute(
    'INSERT INTO change_history (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at) VALUES (:targetType, :targetId, :changeType, now(), CAST(:userId AS bigint), :beforeContent, :afterContent, now(), now())',
    {
      targetType: 'project',
      targetId: projectId,
      changeType,
      userId,
      beforeContent: before === null ? null : JSON.stringify(before),
      afterContent: after === null ? null : JSON.stringify(after),
    },
  );
}

async function assertCodeFree(db: Db, code: string, exceptId: number | null): Promise<void> {
  const rows = await db.query(
    'SELECT project_id FROM project WHERE project_code = :code AND (CAST(:exceptId AS bigint) IS NULL OR project_id <> CAST(:exceptId AS bigint))',
    { code, exceptId },
  );
  if (rows.length > 0) {
    throw new ApiError(409, 'PROJECT_CODE_DUPLICATED', '이미 사용 중인 프로젝트 코드입니다.');
  }
}

function summary(p: ReturnType<typeof parseProject>) {
  const { permittedIds, ...rest } = p;
  return { ...rest, permittedEmployeeIds: permittedIds };
}

function parseProjectId(req: Request): number {
  const raw = req.params['projectId'];
  if (typeof raw !== 'string' || !/^\d+$/.test(raw)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트 ID가 올바르지 않습니다.');
  }
  return Number(raw);
}

@Controller('api/v1')
export class FnSfr00201Controller {
  @Post('/projects')
  @HttpCode(200)
  async createProject(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const p = parseProject(data);
    return transaction(async (db: Db) => {
      await verifyReferences(db, p);
      await assertCodeFree(db, p.projectCode, null);
      const rows = await db.query(
        'INSERT INTO project (project_code, project_name, project_short_name, managing_account, business_type, project_type, start_date, end_date, department_id, manager_id, amount, purpose, content, use_status, created_at, updated_at) VALUES (:projectCode, :projectName, :projectShortName, :managingAccount, :businessType, :projectType, CAST(:startDate AS date), CAST(:endDate AS date), :departmentId, :managerId, CAST(:amount AS numeric), :purpose, :content, :useStatus, now(), now()) RETURNING project_id AS "projectId"',
        {
          projectCode: p.projectCode,
          projectName: p.projectName,
          projectShortName: p.projectShortName,
          managingAccount: p.managingAccount,
          businessType: p.businessType,
          projectType: p.projectType,
          startDate: p.startDate,
          endDate: p.endDate,
          departmentId: p.departmentId,
          managerId: p.managerId,
          amount: p.amount,
          purpose: p.purpose,
          content: p.content,
          useStatus: INITIAL_USE_STATUS,
        },
      );
      const projectId = Number(rows[0].projectId);
      await savePermissions(db, projectId, p.permittedIds);
      await writeHistory(db, projectId, '등록', user.id, null, summary(p));
      return { projectId };
    });
  }

  @Put('/projects/:projectId')
  async updateProject(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const projectId = parseProjectId(req);
    const data = checks.inputOf(req.body);
    const p = parseProject(data);
    return transaction(async (db: Db) => {
      const before = await db.query(
        'SELECT project_id AS "projectId", project_code AS "projectCode", project_name AS "projectName", project_short_name AS "projectShortName", managing_account AS "managingAccount", business_type AS "businessType", project_type AS "projectType", CAST(start_date AS text) AS "startDate", CAST(end_date AS text) AS "endDate", department_id AS "departmentId", manager_id AS "managerId", amount AS "amount", purpose AS "purpose", content AS "content" FROM project WHERE project_id = :projectId',
        { projectId },
      );
      if (before.length === 0) {
        throw new ApiError(404, 'PROJECT_NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
      }
      await verifyReferences(db, p);
      await assertCodeFree(db, p.projectCode, projectId);
      await db.execute(
        'UPDATE project SET project_code = :projectCode, project_name = :projectName, project_short_name = :projectShortName, managing_account = :managingAccount, business_type = :businessType, project_type = :projectType, start_date = CAST(:startDate AS date), end_date = CAST(:endDate AS date), department_id = :departmentId, manager_id = :managerId, amount = CAST(:amount AS numeric), purpose = :purpose, content = :content, updated_at = now() WHERE project_id = :projectId',
        {
          projectId,
          projectCode: p.projectCode,
          projectName: p.projectName,
          projectShortName: p.projectShortName,
          managingAccount: p.managingAccount,
          businessType: p.businessType,
          projectType: p.projectType,
          startDate: p.startDate,
          endDate: p.endDate,
          departmentId: p.departmentId,
          managerId: p.managerId,
          amount: p.amount,
          purpose: p.purpose,
          content: p.content,
        },
      );
      await savePermissions(db, projectId, p.permittedIds);
      await writeHistory(db, projectId, '수정', user.id, before[0], summary(p));
      return { projectId };
    });
  }

  @Delete('/projects/:projectId')
  async deleteProject(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const projectId = parseProjectId(req);
    return transaction(async (db: Db) => {
      const before = await db.query(
        'SELECT project_id AS "projectId", project_code AS "projectCode", project_name AS "projectName" FROM project WHERE project_id = :projectId',
        { projectId },
      );
      if (before.length === 0) {
        throw new ApiError(404, 'PROJECT_NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
      }
      const used = await db.query(
        'SELECT sub_project_id FROM sub_project WHERE project_id = :projectId',
        { projectId },
      );
      if (used.length > 0) {
        throw new ApiError(409, 'PROJECT_IN_USE', '사용 이력이 있는 프로젝트는 삭제할 수 없습니다.');
      }
      await db.execute('DELETE FROM project_permission WHERE project_id = :projectId', { projectId });
      await db.execute('DELETE FROM project WHERE project_id = :projectId', { projectId });
      await writeHistory(db, projectId, '삭제', user.id, before[0], null);
      return {};
    });
  }

  @Get('/projects')
  async listProjects(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const pageRaw = query['page'];
    const sizeRaw = query['size'];
    const page = pageRaw === undefined || pageRaw === '' ? 0 : Number(pageRaw);
    const size = sizeRaw === undefined || sizeRaw === '' ? 20 : Number(sizeRaw);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, 200);
    const name = optText(query['projectName'], 200);
    const businessType = optText(query['businessType'], 20);
    if (businessType !== null && !BUSINESS_TYPES.includes(businessType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '사업 구분 값이 올바르지 않습니다.');
    }
    return transaction(async (db: Db) => {
      const where = '(CAST(:projectName AS text) IS NULL OR project_name LIKE (\'%\' || CAST(:projectName AS text) || \'%\')) AND (CAST(:businessType AS text) IS NULL OR business_type = CAST(:businessType AS text))';
      const filter = { projectName: name, businessType };
      const items = await db.query(
        'SELECT project_id AS "projectId", project_code AS "projectCode", project_name AS "projectName", business_type AS "businessType", project_type AS "projectType", start_date AS "startDate", end_date AS "endDate", amount AS "amount" FROM project WHERE ' + where + ' ORDER BY project_id DESC LIMIT :limit OFFSET :offset',
        { ...filter, limit, offset: page * limit },
      );
      const count = await db.query('SELECT COUNT(*) AS "total" FROM project WHERE ' + where, filter);
      return { items, page, size: limit, total: Number(count[0].total) };
    });
  }
}

