import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  DateInput,
  Pager,
  Pairs,
  RefName,
  Select,
  Tiles,
  TextInput,
  call,
  useData,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const BUSINESS_OPTIONS: [string, string][] = [
  ['고유목적사업', '고유목적사업'],
  ['수익사업', '수익사업'],
  ['공통사업', '공통사업'],
];
const TYPE_OPTIONS: [string, string][] = [
  ['공통', '공통'],
  ['직접사업', '직접사업'],
];

interface FormProps {
  role: string;
  initial: Row;
  projectId?: number;
  onDone: (text: string) => void;
}

function ProjectForm({ role, initial, projectId, onDone }: FormProps) {
  const [v, setV] = useState<Row>(initial);
  const [ids, setIds] = useState<number[]>([]);
  const set = (key: string, value: unknown) => setV({ ...v, [key]: value });

  const submit = async () => {
    const required = ['projectCode', 'projectName', 'startDate', 'endDate', 'businessType', 'projectType', 'departmentId', 'managerId'];
    for (const key of required) {
      if (v[key] === undefined || v[key] === null || v[key] === '') {
        throw new Error('필수 값을 모두 입력하세요.');
      }
    }
    if (String(v.endDate) < String(v.startDate)) {
      throw new Error('종료일은 시작일보다 빠를 수 없습니다.');
    }
    const body: Row = { ...v, permittedEmployeeIds: ids };
    if (projectId === undefined) {
      await call('POST', '/projects', role, body);
      onDone('프로젝트를 등록했습니다.');
    } else {
      await call('PUT', '/projects/' + projectId, role, body);
      onDone('프로젝트를 수정했습니다.');
    }
  };

  return (
    <Form
      onSubmit={submit}
      submit={projectId === undefined ? '등록' : '수정'}
      note={projectId === undefined ? undefined : '주관부서·담당자·사용 권한 대상은 다시 선택해야 합니다.'}
    >
      <Field label='프로젝트 코드' required>
        <TextInput value={v.projectCode} onChange={(x) => set('projectCode', x)} />
      </Field>
      <Field label='프로젝트 명칭' required>
        <TextInput value={v.projectName} onChange={(x) => set('projectName', x)} />
      </Field>
      <Field label='프로젝트 약칭'>
        <TextInput value={v.projectShortName} onChange={(x) => set('projectShortName', x)} />
      </Field>
      <Field label='관리계좌'>
        <TextInput value={v.managingAccount} onChange={(x) => set('managingAccount', x)} />
      </Field>
      <Field label='시작일' required>
        <DateInput value={v.startDate} onChange={(x) => set('startDate', x)} />
      </Field>
      <Field label='종료일' required>
        <DateInput value={v.endDate} onChange={(x) => set('endDate', x)} />
      </Field>
      <Field label='사업 구분' required>
        <Select value={v.businessType} onChange={(x) => set('businessType', x)} options={BUSINESS_OPTIONS} />
      </Field>
      <Field label='프로젝트 유형' required>
        <Select value={v.projectType} onChange={(x) => set('projectType', x)} options={TYPE_OPTIONS} />
      </Field>
      <Field label='주관부서' required>
        <LookupSelect table='department' role={role} value={v.departmentId} onChange={(x) => set('departmentId', x)} />
      </Field>
      <Field label='담당자' required>
        <LookupSelect table='employee' role={role} value={v.managerId} onChange={(x) => set('managerId', x)} />
      </Field>
      <Field label='프로젝트 금액'>
        <NumberInput value={v.amount} onChange={(x) => set('amount', x)} />
      </Field>
      <Field label='프로젝트 목적' wide>
        <TextInput multiline value={v.purpose} onChange={(x) => set('purpose', x)} />
      </Field>
      <Field label='프로젝트 내용' wide>
        <TextInput multiline value={v.content} onChange={(x) => set('content', x)} />
      </Field>
      <Field label='사용 권한 대상 임직원' wide hint='비워 두면 권한 제한을 설정하지 않습니다.'>
        <div>
          <LookupSelect
            table='employee'
            role={role}
            value=''
            placeholder='임직원 추가'
            onChange={(x) => {
              if (typeof x === 'number' && !ids.includes(x)) {
                setIds([...ids, x]);
              }
            }}
          />
          {ids.map((id) => (
            <div key={id}>
              <RefName table='employee' role={role} value={id} />
              <button type='button' onClick={() => setIds(ids.filter((i) => i !== id))}>
                제거
              </button>
            </div>
          ))}
        </div>
      </Field>
    </Form>
  );
}

export default function FnSfr00201Page({ role, notify }: PageProps) {
  const [name, setName] = useState('');
  const [business, setBusiness] = useState('');
  const [applied, setApplied] = useState({ name: '', business: '' });
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<'none' | 'create' | 'detail' | 'edit'>('none');
  const [selected, setSelected] = useState<Row | undefined>(undefined);
  const [removeError, setRemoveError] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/projects', role, undefined, { projectName: applied.name, businessType: applied.business, page, size: 20 }),
    [role, applied, page],
  );
  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;

  const close = () => {
    setMode('none');
    setSelected(undefined);
    setRemoveError('');
  };
  const done = (text: string) => {
    notify(text);
    close();
    list.reload();
  };

  const remove = async () => {
    if (!selected) {
      return;
    }
    try {
      await call('DELETE', '/projects/' + selected.projectId, role);
      done('프로젝트를 삭제했습니다.');
    } catch (e) {
      setRemoveError(e instanceof Error ? e.message : '삭제하지 못했습니다.');
    }
  };

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>전체 프로젝트</h2>
        <Tiles items={[['건수', <Num value={total} />]]} />
      </section>
      <section className='box span-12'>
        <h2>프로젝트 목록</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied({ name, business });
          }}
          onReset={() => {
            setName('');
            setBusiness('');
            setPage(0);
            setApplied({ name: '', business: '' });
          }}
        >
          <Field label='프로젝트 명칭'>
            <TextInput value={name} onChange={setName} />
          </Field>
          <Field label='사업 구분'>
            <Select value={business} onChange={setBusiness} options={BUSINESS_OPTIONS} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type='button' onClick={() => setMode('create')}>
            프로젝트 등록
          </button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={rows}
          empty='프로젝트가 없습니다.'
          onRowClick={(row) => {
            setSelected(row);
            setMode('detail');
          }}
          columns={[
            { key: 'projectCode', label: '프로젝트 코드' },
            { key: 'projectName', label: '프로젝트 명칭' },
            { key: 'businessType', label: '사업 구분', render: (r) => <Badge value={r.businessType} /> },
            { key: 'projectType', label: '프로젝트 유형' },
            { key: 'startDate', label: '시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'endDate', label: '종료일', render: (r) => <DateText value={r.endDate} /> },
            { key: 'amount', label: '프로젝트 금액', render: (r) => <Num value={r.amount} /> },
          ]}
        />
        <Pager page={page} size={20} total={total} onPage={setPage} />
      </section>
      {mode === 'create' ? (
        <Drawer title='프로젝트 등록' onClose={close}>
          <ProjectForm role={role} initial={{}} onDone={done} />
        </Drawer>
      ) : null}
      {mode === 'detail' && selected ? (
        <Drawer title='프로젝트 상세' onClose={close}>
          <Pairs
            items={[
              ['프로젝트 코드', String(selected.projectCode)],
              ['프로젝트 명칭', String(selected.projectName)],
              ['사업 구분', <Badge value={selected.businessType} />],
              ['프로젝트 유형', String(selected.projectType)],
              ['시작일', <DateText value={selected.startDate} />],
              ['종료일', <DateText value={selected.endDate} />],
              ['프로젝트 금액', <Num value={selected.amount} />],
            ]}
          />
          {removeError ? <p>{removeError}</p> : null}
          <button type='button' onClick={() => setMode('edit')}>
            수정
          </button>
          <button type='button' onClick={remove}>
            삭제
          </button>
        </Drawer>
      ) : null}
      {mode === 'edit' && selected ? (
        <Drawer title='프로젝트 수정' onClose={close}>
          <ProjectForm
            role={role}
            projectId={Number(selected.projectId)}
            initial={{
              projectCode: selected.projectCode,
              projectName: selected.projectName,
              businessType: selected.businessType,
              projectType: selected.projectType,
              startDate: String(selected.startDate).slice(0, 10),
              endDate: String(selected.endDate).slice(0, 10),
              amount: selected.amount,
            }}
            onDone={done}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
